def tri(n):
    if n == 0:
        return [1]
    arr = [0] * (n + 1)
    arr[0] = 1
    arr[1] = 3
    for i in range(2, n + 1):
        if i % 2 == 0:
            arr[i] = 1 + i // 2
        else:
            arr[i] = arr[i - 1] + arr[i - 2] + arr[i + 1]
    return arr[:n + 1]
